        this.id = id;
        this.content = content;
        this.createAt = createAt;
        this.clarificationConversation = clarificationConversation;
        this.user = user;
    }

    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getContent() {
        return content;
    }

    public void setContent(String content) {
        this.content = content;
    }

