package nvt.vn.ute_forum.service;

import nvt.vn.ute_forum.model.ClarificationConversation;
import nvt.vn.ute_forum.model.Message;
import nvt.vn.ute_forum.model.Users;
import nvt.vn.ute_forum.repository.MessageRepo;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

@Service
public class MessageService {
    private static final String PAYLOAD_PREFIX = "CHAT_V1::";
    private static final String LEGACY_PAYLOAD_PREFIX = "CHAT_JSON::";
    private static final String ATTACHMENT_SECTION_SEPARATOR = "\n--FILES--\n";
    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");

    private final MessageRepo messageRepo;
    private final IdGeneratorService idGeneratorService;

    @Value("${app.upload.dir:uploads/}")
    private String uploadDir;

    public MessageService(MessageRepo messageRepo,
                          IdGeneratorService idGeneratorService) {
        this.messageRepo = messageRepo;
        this.idGeneratorService = idGeneratorService;
    }

    @Transactional(readOnly = true)
    public List<ChatMessageView> getConversationMessages(String conversationId, String currentUserId) {
        if (conversationId == null || conversationId.isBlank()) {
            return Collections.emptyList();
        }

        return messageRepo.findByClarificationConversation_IdOrderByCreateAtAscIdAsc(conversationId)
                .stream()
                .map(message -> toView(message, currentUserId))
                .toList();
    }

    @Transactional
    public ChatMessageView saveMessage(ClarificationConversation conversation,
                                       Users sender,
                                       String text,
                                       List<ChatAttachment> attachments,
                                       String currentUserId) {
        Message message = new Message();
        message.setId(idGeneratorService.nextMessageId());
        message.setClarificationConversation(conversation);
        message.setUser(sender);
        message.setCreateAt(LocalDateTime.now());
        message.setContent(serializePayload(text, attachments));

        Message saved = messageRepo.save(message);
        return toView(saved, currentUserId);
    }

    public List<ChatAttachment> storeChatFiles(String requestId, MultipartFile[] files) throws IOException {
        if (files == null || files.length == 0) {
            return Collections.emptyList();
        }

        Path uploadRoot = Paths.get(uploadDir).toAbsolutePath().normalize();
        Files.createDirectories(uploadRoot);

        List<ChatAttachment> attachments = new ArrayList<>();
        for (MultipartFile file : files) {
            if (file == null || file.isEmpty()) {
                continue;
            }

            String originalName = file.getOriginalFilename() == null
                    ? "file"
                    : Paths.get(file.getOriginalFilename()).getFileName().toString();
            String extension = "";
            int dotIndex = originalName.lastIndexOf('.');
            if (dotIndex >= 0) {
                extension = originalName.substring(dotIndex);
            }

            String normalizedRequestId = (requestId == null || requestId.isBlank()) ? "REQ_UNKNOWN" : requestId;
            String storedFileName = normalizedRequestId + "_CHAT_" + System.nanoTime() + extension;
            Path target = uploadRoot.resolve(storedFileName);
            Files.copy(file.getInputStream(), target, StandardCopyOption.REPLACE_EXISTING);

            String contentType = file.getContentType();
            attachments.add(new ChatAttachment(
                    originalName,
                    "/uploads/" + storedFileName,
                    contentType == null ? "application/octet-stream" : contentType
            ));
        }
        return attachments;
    }

    private ChatMessageView toView(Message message, String currentUserId) {
        MessagePayload payload = deserializePayload(message.getContent());
        String senderId = message.getUser() == null ? "" : nullSafe(message.getUser().getId());
        String senderName = message.getUser() == null ? "Người dùng" : nullSafe(message.getUser().getFullName());
        String timeLabel = message.getCreateAt() == null ? "" : message.getCreateAt().format(DATE_FORMATTER);

        return new ChatMessageView(
                message.getId(),
                senderId,
                senderName,
                payload.text(),
                payload.attachments(),
                timeLabel,
                currentUserId != null && currentUserId.equals(senderId)
        );
    }

    private String serializePayload(String text, List<ChatAttachment> attachments) {
        String normalizedText = escape(normalizeText(text));
        List<ChatAttachment> sanitizedAttachments = safeAttachments(attachments);
        if (sanitizedAttachments.isEmpty()) {
            return PAYLOAD_PREFIX + normalizedText;
        }

        StringBuilder builder = new StringBuilder(PAYLOAD_PREFIX)
                .append(normalizedText)
                .append(ATTACHMENT_SECTION_SEPARATOR);

        for (ChatAttachment attachment : sanitizedAttachments) {
            builder.append(escape(nullSafe(attachment.name())))
                    .append('|')
                    .append(escape(attachment.url()))
                    .append('|')
                    .append(escape(nullSafe(attachment.type())))
                    .append('\n');
        }
        return builder.toString();
    }

    private MessagePayload deserializePayload(String rawContent) {
        if (rawContent == null || rawContent.isBlank()) {
            return new MessagePayload("", Collections.emptyList());
        }

        if (rawContent.startsWith(LEGACY_PAYLOAD_PREFIX)) {
            String legacyText = rawContent.substring(LEGACY_PAYLOAD_PREFIX.length());
            return new MessagePayload(legacyText, Collections.emptyList());
        }

        if (!rawContent.startsWith(PAYLOAD_PREFIX)) {
            return new MessagePayload(rawContent, Collections.emptyList());
        }

        String payload = rawContent.substring(PAYLOAD_PREFIX.length());
        int separatorIndex = payload.indexOf(ATTACHMENT_SECTION_SEPARATOR);
        if (separatorIndex < 0) {
            return new MessagePayload(unescape(payload), Collections.emptyList());
        }

        String textPart = payload.substring(0, separatorIndex);
        String attachmentPart = payload.substring(separatorIndex + ATTACHMENT_SECTION_SEPARATOR.length());

        List<ChatAttachment> attachments = new ArrayList<>();
        String[] lines = attachmentPart.split("\\n");
        for (String line : lines) {
            if (line == null || line.isBlank()) {
                continue;
            }
            List<String> fields = splitEscaped(line, '|', 3);
            if (fields.size() < 2) {
                continue;
            }

            String name = fields.get(0);
            String url = fields.get(1);
            String type = fields.size() >= 3 ? fields.get(2) : "application/octet-stream";
            if (url == null || url.isBlank()) {
                continue;
            }
            attachments.add(new ChatAttachment(
                    unescape(name),
                    unescape(url),
                    unescape(type)
            ));
        }

        return new MessagePayload(unescape(textPart), safeAttachments(attachments));
    }

    private List<ChatAttachment> safeAttachments(List<ChatAttachment> attachments) {
        if (attachments == null || attachments.isEmpty()) {
            return Collections.emptyList();
        }
        return attachments.stream()
                .filter(att -> att != null && att.url() != null && !att.url().isBlank())
                .map(att -> new ChatAttachment(
                        nullSafe(att.name()),
                        att.url(),
                        att.type() == null || att.type().isBlank() ? "application/octet-stream" : att.type()
                ))
                .toList();
    }

    private String normalizeText(String text) {
        return text == null ? "" : text.trim();
    }

    private String escape(String value) {
        if (value == null || value.isBlank()) {
            return "";
        }
        return value
                .replace("\\", "\\\\")
                .replace("|", "\\|")
                .replace("\n", "\\n")
                .replace("\r", "");
    }

    private String unescape(String value) {
        if (value == null || value.isBlank()) {
            return "";
        }

        StringBuilder builder = new StringBuilder();
        boolean escaped = false;
        for (int i = 0; i < value.length(); i++) {
            char ch = value.charAt(i);
            if (escaped) {
                if (ch == 'n') {
                    builder.append('\n');
                } else {
                    builder.append(ch);
                }
                escaped = false;
                continue;
            }

            if (ch == '\\') {
                escaped = true;
                continue;
            }

            builder.append(ch);
        }

        if (escaped) {
            builder.append('\\');
        }
        return builder.toString();
    }

    private List<String> splitEscaped(String value, char separator, int maxParts) {
        List<String> parts = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        boolean escaped = false;

        for (int i = 0; i < value.length(); i++) {
            char ch = value.charAt(i);

            if (escaped) {
                current.append(ch);
                escaped = false;
                continue;
            }

            if (ch == '\\') {
                escaped = true;
                current.append(ch);
                continue;
            }

            if (ch == separator && parts.size() < maxParts - 1) {
                parts.add(current.toString());
                current.setLength(0);
                continue;
            }

            current.append(ch);
        }

        parts.add(current.toString());
        return parts;
    }

    private String nullSafe(String value) {
        return value == null ? "" : value;
    }

    public record ChatAttachment(String name, String url, String type) {
    }

    public record ChatMessageView(String id,
                                  String senderId,
                                  String senderName,
                                  String text,
                                  List<ChatAttachment> attachments,
                                  String time,
                                  boolean mine) {
    }

    private record MessagePayload(String text, List<ChatAttachment> attachments) {
    }

}

/* ===== ROOT ===== */


:root {
    --sidebar-bg: #04163f;
    --sidebar-muted: #9fb5de;
    --sidebar-active: #1f2f50;
    --surface: #f4f7fb;
    --card: #ffffff;
    --line: #dbe2ec;
    --line-strong: #c9d2e1;
    --text: #0f172a;
    --muted: #6b7280;
    --primary: #1e40af;
}

* {
    box-sizing: border-box;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: visible;
    clip: rect(0, 0, 0, 0);
    border: 0;
}

body {
    margin: 0;
    font-family: "Segoe UI", Arial, Helvetica, sans-serif;
    color: var(--text);
    background: #eceff4;
}

.page-layout {
    min-height: 100vh;
    display: grid;
    grid-template-columns: 250px minmax(0, 1fr);
}

.sidebar {
    background: #00558b;
    color: #fff;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #0b2558;
    position: sticky;
    top: 0;              /*  bắt buộc */
    height: 100vh;       /* để full chiều cao */
    align-self: start;   /* fix bug grid */
}

.brand-block {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 22px 16px 18px;
    border-bottom: 1px solid #9aa0af;
}

.brand-logo {
    width: 118px;
    height: 150px;
    object-fit: cover;
    margin-bottom: 14px;
}


.student-info {
    width: 100%;
    text-align: left;
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 8px;
    padding-top: 12px;
    position: relative;
}

.student-info::before {
    content: "";
    position: absolute;
    top: 0;
    left: -16px;
    right: -16px;
    border-top: 1px solid #9aa0af;
}

.avatar {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.08);
}

.student-info p {
    margin: 2px 0;
    font-size: 15px;
    color: var(--sidebar-muted);
}

.student-name {
    color: #f5f8ff !important;
    font-weight: 700;
    font-size: 16px;
}

.student-id {
    color: #d7e4ff !important;
}

.sidebar-nav {
    margin-top: 16px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 0 12px;
}

.nav-item {
    display: flex;
    align-items: center;
    gap: 10px;
    color: #d7e4ff;
    text-decoration: none;
    padding: 10px 12px;
    border-radius: 10px;
    font-size: 15px;
    letter-spacing: 0.3px;    font-weight: 600;
    border: 1px solid transparent;
    transition: background 0.2s ease, border-color 0.2s ease;
}

.badge-count {
  margin-left: auto;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: #ef233c;
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.nav-icon {
    filter: grayscale(100%) brightness(1.5);
    width: 24px;
    height: 24px;
    border-radius: 7px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.08);
    font-size: 12px;
}

.nav-item:hover,
.nav-item.active {
    background: var(--sidebar-active);
    border-color: rgba(159, 181, 222, 0.35);
}

.logout-btn {
    margin-top: auto;
    display: block;
    color: #dce9ff;
    text-decoration: none;
    padding: 12px 20px;
    border-top: 1px solid #163364;
}

.main-content {
    padding: 0 10px 10px;
}

.main-header {
    margin-bottom: 10px;

    border-top: 0;
    /*background: #ffffff;*/
}

.school-title {
    margin: 0;
    font-size: 20px;
    font-weight: 700;
    color: #ababab;
    letter-spacing: 0.3px;
}

.main-header-top {
    background: #00558b;
    border-top: 3px solid #0c79b4;
    padding: 5px 32px;
}

.main-header-bottom {
    min-height: 58px;
    border-top: 1px solid #b8bec8;
    border-bottom: 2px solid #ccc;
    padding: 22px 0 0 5px;
}


.page-tab {
    margin: 0;
    position: relative;
    display: inline-flex;
    align-items: center;
    background: #00558b;
    color: #ffffff;
    font-size: 20px;
    font-weight: 700;
    line-height: 1;
    padding: 5px 22px;
    letter-spacing: 0.3px;
}

.page-tab::after {
    content: "";
    position: absolute;
    top: 0;
    right: -20px;

    width: 0;
    height: 0;

    border-bottom: 28px solid #7d7d7d; /*  đổi ở đây */
    border-right: 20px solid transparent;
}


.history-panel {
  min-height: calc(100vh - 20px);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  padding: 10px;
}

.toolbar {
  display: flex;
  gap: 6px;
  padding: 6px;
  border-radius: 12px;
}

.search-input,
.filter-group select {
  background: #fff;
  color: var(--text);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  height: 34px;
  padding: 0 10px;
  font-size: 14px;
}

.search-input {
  flex: 1;
}

.filter-group {
  display: flex;
  gap: 8px;
}

.filter-btn {
  height: 34px;
  border-radius: 8px;
  border: 1px solid #cbd5e1;
  background: #fff;
  color: #334155;
  font-size: 14px;
  font-weight: 600;
  padding: 0 10px;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.filter-btn.apply {
  border-color: #2563eb;
  background: #2563eb;
  color: #fff;
}

.filter-btn.reset {
  border-color: #cbd5e1;
  background: #f8fafc;
}

.feedback-grid {
  flex: 1;
  margin-top: 10px;
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  background: #f8fafc;
  padding: 12px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-auto-rows: max-content;
  align-content: start;
  align-items: start;
  gap: 12px;
  overflow-y: auto;
}

.feedback-card {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--card);
  min-height: 220px;
  padding: 10px 0 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: hidden;
}

.card-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 3px 9px;
  font-size: 11px;
  font-weight: 700;
  border: 1px solid #d5dbe5;
  background: #eef2f7;
  color: #475569;
}

.status-pill.done {
  color: #0f766e;
  background: #dcfce7;
  border-color: #86efac;
}

.status-pill.processing {
  color: #1d4ed8;
  background: #dbeafe;
  border-color: #93c5fd;
}

.status-pill.waiting {
  color: #b45309;
  background: #ffedd5;
  border-color: #fdba74;
}


.status-pill.pending {
  color: #b45309;
  background: #ffedd5;
  border-color: #fdba74;
}

.status-pill.forwarding {
  color: #6b21a8;
  background: #f3e8ff;
  border-color: #e9d5ff;
}

.status-pill.approved {
  color: #1d4ed8;
  background: #dbeafe;
  border-color: #93c5fd;
}

.status-pill.rejected {
  color: #991b1b;
  background: #fee2e2;
  border-color: #fecaca;
}
.request-subject {
  margin: 0;
  padding: 0 12px;
  font-size: 16px;
  line-height: 1.2;
}

.request-description {
  margin: 0;
  color: #475569;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.request-meta-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 12px;
}

.request-meta {
  margin: 0;
  font-size: 12px;
  color: #475569;
  line-height: 1.4;
}

.request-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 8px;
  background: #eef2f7;
  color: #334155;
    font-size: 12.5px;
}

.meta-icon {
  font-size: 1rem;
  opacity: 0.5;
  vertical-align: middle;
  margin-right: 6px;
  filter: grayscale(1); /* Làm icon tiệp với màu chữ để sang hơn */
}

.card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: auto;
  border-top: 1px solid #e2e8f0;
  padding: 8px 12px;
}

.detail-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 3px 6px;
  border-radius: 6px;
  border: 1px solid transparent;
  color: #1d4ed8;
  text-decoration: none;
  font-weight: 600;
  font-size: 12px;
}

.detail-btn::after {
  content: ">";
  font-size: 12px;
}

.detail-btn:hover {
  background: #eff6ff;
  border-color: #bfdbfe;
}

.request-date {
  color: #8ba0bd;
  font-size: 12px;
}

.request-detail {
  margin-top: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.detail-header {
  display: flex;
}

.back-link {
  text-decoration: none;
  color: #1d4ed8;
  font-weight: 600;
}

.detail-top-card {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  padding: 12px;
}

.detail-top-card h2 {
  margin: 0 0 12px;
    font-size: 18px;
}

.detail-top-card h3 {
  margin: 14px 0 8px;
}

.detail-meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.meta-chip {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 2px 8px;
  border: 1px solid #d5dbe5;
  background: #f8fafc;
  color: #475569;
  font-size: 11px;
  font-weight: 600;
}

.detail-description {
  margin: 0;
  color: #334155;
  line-height: 1.6;
    font-size: 14px;
}

.detail-bottom-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.detail-panel {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  min-height: 300px;
  padding: 14px;
}

.detail-panel h3 {
  margin: 0 0 12px;
}

.timeline {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.timeline::before {
  content: "";
  position: absolute;
  left: 8px;
  top: 10px;
  bottom: 10px;
  width: 2px;
  background: #bfdbfe;
}

.timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 18px 1fr;
  gap: 10px;
  margin: 0;
}

.timeline-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #3b82f6;
  margin-top: 8px;
}

.timeline-card {
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: #f8fafc;
  padding: 10px;
}

.timeline-head {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
}

.timeline-head-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.timeline-type {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 3px 8px;
  font-size: 11px;
  font-weight: 700;
  color: #334155;
  background: #e2e8f0;
}

.timeline-head time {
  color: #64748b;
  font-size: 12px;
}

.timeline-card p {
  margin: 8px 0 0;
  color: #334155;
}

.timeline-empty {
  border: 1px dashed #cbd5e1;
  border-radius: 10px;
  padding: 12px;
  color: #64748b;
  background: #f8fafc;
}

.chat-empty {
  min-height: 220px;
  border: 1px dashed #cbd5e1;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
}

.pagination {
  margin-top: 10px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  color: #243047;
  font-weight: 600;
    font-size: 13px;
}

.page-btn {
  width: 28px;
  height: 28px;
  border: 1px solid var(--line-strong);
  border-radius: 7px;
  color: #64748b;
  background: #fff;
  cursor: pointer;
    font-size: 12px;

}

.page-btn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.empty-state {
  grid-column: 1 / -1;
  min-height: 220px;
  border: 2px dashed var(--line-strong);
  border-radius: 12px;
  background: #fff;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  color: #475569;
}

.empty-state h3 {
  margin: 0 0 8px;
  font-size: 18px;
  color: #0f172a;
}

.empty-state p {
  margin: 0;
}

.btn-action {
    display: inline-block;
    padding: 8px 16px;
    border-radius: 4px;
    text-decoration: none;
    font-size: 14px;
    cursor: pointer;
    border: 1px solid transparent;
}

/* nút sửa */
.btn-edit {
    background-color: #f0f0f0;
    color: #333;
    border-color: #ccc;
}

/* nút xóa */
.btn-delete {
    background-color: #d9534f;
    color: white;
    border-color: #d9534f;
}

/* hover đẹp hơn */
.btn-action:hover {
    opacity: 0.85;
}
@media (max-width: 980px) {
  .page-layout {
    grid-template-columns: 1fr;
  }

  .sidebar {
    flex-direction: row;
    align-items: center;
    gap: 10px;
    border-right: 0;
    border-bottom: 1px solid #163364;
    padding: 10px;
  }

  .brand-block {
    border-bottom: 0;
    padding: 0;
    flex-direction: row;
    gap: 10px;
  }

  .brand-logo {
    width: 56px;
    height: 56px;
    margin-bottom: 0;
  }

  .student-info {
    text-align: left;
    margin-top: 0;
    padding-top: 0;
  }

  .student-info::before {
    display: none;
  }

  .sidebar-nav {
    margin: 0;
    flex: 1;
    flex-direction: row;
    flex-wrap: wrap;
  }

  .main-header h1 {
    font-size: 22px;
  }

  .logout-btn {
    margin-top: 0;
    border-top: 0;
    padding: 10px 12px;
  }
}

@media (max-width: 680px) {
  .main-header-top {
    padding: 10px 12px;
  }

  .school-title {
    font-size: 20px;
  }

  .main-header-bottom {
    padding: 14px 0 0 12px;
    min-height: 62px;
  }

  .page-tab {
    font-size: 18px;
    padding: 10px 14px;
  }

  .page-tab::after {
    border-top-width: 19px;
    border-bottom-width: 19px;
  }

  .toolbar {
    flex-direction: column;
  }

  .filter-group {
    flex-direction: column;
  }

  .filter-btn {
    width: 100%;
  }

  .feedback-grid {
    grid-template-columns: 1fr;
  }

  .detail-bottom-grid {
    grid-template-columns: 1fr;
  }
}

/* ===== ROOT ===== */


:root {
    --sidebar-bg: #04163f;
    --sidebar-muted: #9fb5de;
    --sidebar-active: #1f2f50;
    --surface: #f4f7fb;
    --card: #ffffff;
    --line: #dbe2ec;
    --line-strong: #c9d2e1;
    --text: #0f172a;
    --muted: #6b7280;
    --primary: #1e40af;
}

* {
    box-sizing: border-box;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: visible;
    clip: rect(0, 0, 0, 0);
    border: 0;
}

body {
    margin: 0;
    font-family: "Segoe UI", Arial, Helvetica, sans-serif;
    color: var(--text);
    background: #eceff4;
}

.page-layout {
    min-height: 100vh;
    display: grid;
    grid-template-columns: 250px minmax(0, 1fr);
}

.sidebar {
    background: #00558b;
    color: #fff;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #0b2558;
    position: sticky;
    top: 0;              /*  bắt buộc */
    height: 100vh;       /* để full chiều cao */
    align-self: start;   /* fix bug grid */
}

.brand-block {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 22px 16px 18px;
    border-bottom: 1px solid #9aa0af;
}

.brand-logo {
    width: 118px;
    height: 150px;
    object-fit: cover;
    margin-bottom: 14px;
}


.student-info {
    width: 100%;
    text-align: left;
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 8px;
    padding-top: 12px;
    position: relative;
}

.student-info::before {
    content: "";
    position: absolute;
    top: 0;
    left: -16px;
    right: -16px;
    border-top: 1px solid #9aa0af;
}

.avatar {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.08);
}

.student-info p {
    margin: 2px 0;
    font-size: 15px;
    color: var(--sidebar-muted);
}

.student-name {
    color: #f5f8ff !important;
    font-weight: 700;
    font-size: 16px;
}

.student-id {
    color: #d7e4ff !important;
}

.sidebar-nav {
    margin-top: 16px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 0 12px;
}

.nav-item {
    display: flex;
    align-items: center;
    gap: 10px;
    color: #d7e4ff;
    text-decoration: none;
    padding: 10px 12px;
    border-radius: 10px;
    font-size: 15px;
    letter-spacing: 0.3px;    font-weight: 600;
    border: 1px solid transparent;
    transition: background 0.2s ease, border-color 0.2s ease;
}

.badge-count {
  margin-left: auto;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: #ef233c;
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.nav-icon {
    filter: grayscale(100%) brightness(1.5);
    width: 24px;
    height: 24px;
    border-radius: 7px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.08);
    font-size: 12px;
}

.nav-item:hover,
.nav-item.active {
    background: var(--sidebar-active);
    border-color: rgba(159, 181, 222, 0.35);
}

.logout-btn {
    margin-top: auto;
    display: block;
    color: #dce9ff;
    text-decoration: none;
    padding: 12px 20px;
    border-top: 1px solid #163364;
}

.main-content {
    padding: 0 10px 10px;
}

.main-header {
    margin-bottom: 10px;

    border-top: 0;
    /*background: #ffffff;*/
}

.school-title {
    margin: 0;
    font-size: 20px;
    font-weight: 700;
    color: #ababab;
    letter-spacing: 0.3px;
}

.main-header-top {
    background: #00558b;
    border-top: 3px solid #0c79b4;
    padding: 5px 32px;
}

.main-header-bottom {
    min-height: 58px;
    border-top: 1px solid #b8bec8;
    border-bottom: 2px solid #ccc;
    padding: 22px 0 0 5px;
}


.page-tab {
    margin: 0;
    position: relative;
    display: inline-flex;
    align-items: center;
    background: #00558b;
    color: #ffffff;
    font-size: 20px;
    font-weight: 700;
    line-height: 1;
    padding: 5px 22px;
    letter-spacing: 0.3px;
}

.page-tab::after {
    content: "";
    position: absolute;
    top: 0;
    right: -20px;

    width: 0;
    height: 0;

    border-bottom: 28px solid #7d7d7d; /*  đổi ở đây */
    border-right: 20px solid transparent;
}


.history-panel {
  min-height: calc(100vh - 20px);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  padding: 10px;
}

.toolbar {
  display: flex;
  gap: 6px;
  padding: 6px;
  border-radius: 12px;
}

.search-input,
.filter-group select {
  background: #fff;
  color: var(--text);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  height: 34px;
  padding: 0 10px;
  font-size: 14px;
}

.search-input {
  flex: 1;
}

.filter-group {
  display: flex;
  gap: 8px;
}

.filter-btn {
  height: 34px;
  border-radius: 8px;
  border: 1px solid #cbd5e1;
  background: #fff;
  color: #334155;
  font-size: 14px;
  font-weight: 600;
  padding: 0 10px;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.filter-btn.apply {
  border-color: #2563eb;
  background: #2563eb;
  color: #fff;
}

.filter-btn.reset {
  border-color: #cbd5e1;
  background: #f8fafc;
}

.feedback-grid {
  flex: 1;
  margin-top: 10px;
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  background: #f8fafc;
  padding: 12px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-auto-rows: max-content;
  align-content: start;
  align-items: start;
  gap: 12px;
  overflow-y: auto;
}

.feedback-card {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--card);
  min-height: 220px;
  padding: 10px 0 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: hidden;
}

.card-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 3px 9px;
  font-size: 11px;
  font-weight: 700;
  border: 1px solid #d5dbe5;
  background: #eef2f7;
  color: #475569;
}

