}

.timeline-card p {
  margin: 8px 0 0;
  color: #334155;
}

.timeline-empty {
  border: 1px dashed #cbd5e1;
  border-radius: 10px;
  padding: 12px;
  color: #64748b;
  background: #f8fafc;
}

.chat-empty {
  min-height: 220px;
  border: 1px dashed #cbd5e1;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
}

.chat-empty.compact {
  min-height: 140px;
  background: #ffffff;
}

.conversation-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.conversation-item {
  width: 100%;
  border: 1px solid #d7dee8;
  border-radius: 14px;
  background: #ffffff;
  padding: 14px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 12px;
  text-align: left;
  cursor: pointer;
}

.conversation-item:hover {
  border-color: #c4d4ef;
  box-shadow: 0 2px 10px rgba(59, 130, 246, 0.08);
}

.conversation-item.active {
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

.conversation-item-icon {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #ecf1f8;
  color: #64748b;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: 2px;
}

.conversation-item-main h4 {
  margin: 0;
  font-size: 32px;
  color: #0f172a;
  line-height: 1.25;
}

.conversation-item-main p {
  margin: 4px 0 8px;
  color: #64748b;
  font-size: 14px;
}

.conversation-item time {
  color: #7185ab;
  font-size: 13px;
  white-space: nowrap;
}

.conversation-open-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 3px 10px;
  background: #dcfce7;
  color: #166534;
  font-size: 12px;
  font-weight: 700;
}

.chat-drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(2, 6, 23, 0.32);
  z-index: 1200;
}

.chat-drawer {
  position: fixed;
  top: 0;
  right: -440px;
  width: 410px;
  max-width: 95vw;
  height: 100vh;
  border-left: 1px solid #e2e8f0;
  background: #ffffff;
  display: grid;
  grid-template-rows: auto 1fr auto;
  z-index: 1300;
  transition: right 0.25s ease;
}

.chat-drawer.open {
  right: 0;
}

.chat-drawer-header {
  padding: 16px;
  border-bottom: 1px solid #e2e8f0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
}

.chat-drawer-header h3 {
  margin: 0;
  font-size: 34px;
  color: #0f172a;
  line-height: 1.3;
}

.chat-drawer-header p {
  margin: 6px 0 0;
  color: #64748b;
  font-size: 13px;
}

.chat-drawer-close {
  border: 0;
  background: transparent;
  color: #64748b;
  font-size: 24px;
  line-height: 1;
  cursor: pointer;
}

.chat-drawer-message-list {
  overflow-y: auto;
  padding: 14px;
  background: #f8fafc;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.chat-drawer-compose {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 42px;
  gap: 8px;
  align-items: center;
  padding: 10px 12px;
  border-top: 1px solid #e2e8f0;
  background: #ffffff;
}

.chat-attach-btn {
  width: 34px;
  height: 34px;
  border: 1px solid #d7dee8;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
  cursor: pointer;
  user-select: none;
}

.chat-drawer-compose input[type="text"] {
  width: 100%;
  border: 1px solid #d7dee8;
  border-radius: 10px;
  height: 38px;
  padding: 0 10px;
}

.chat-send-btn {
  width: 42px;
  height: 38px;
  border: 0;
  border-radius: 10px;
  background: #3b82f6;
  color: #ffffff;
  cursor: pointer;
}

.chat-message {
  max-width: 85%;
  border: 1px solid #dbe6f3;
  border-radius: 10px;
  background: #ffffff;
  padding: 8px 10px;
}

.chat-message.mine {
  margin-left: auto;
  border-color: #bfdbfe;
  background: #eff6ff;
}

.chat-message-meta {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  font-size: 12px;
  color: #64748b;
}

.chat-message-text {
  margin: 6px 0 0;
  white-space: pre-wrap;
  line-height: 1.5;
  color: #1e293b;
}

.chat-attachment-list {
  margin: 8px 0 0;
  padding-left: 18px;
}

.chat-attachment-list a {
  color: #1d4ed8;
  text-decoration: none;
}

.chat-attachment-list a:hover {
  text-decoration: underline;
}

.chat-message-time {
  margin-top: 6px;
  font-size: 11px;
  color: rgba(100, 116, 139, 0.75);
}

.chat-message.mine .chat-message-time {
  color: rgba(59, 130, 246, 0.72);
}


.pagination {
  margin-top: 10px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  color: #243047;
  font-weight: 600;
    font-size: 13px;
}

.page-btn {
  width: 28px;
  height: 28px;
  border: 1px solid var(--line-strong);
  border-radius: 7px;
  color: #64748b;
  background: #fff;
  cursor: pointer;
    font-size: 12px;

}

.page-btn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.empty-state {
  grid-column: 1 / -1;
  min-height: 220px;
  border: 2px dashed var(--line-strong);
  border-radius: 12px;
  background: #fff;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  color: #475569;
}

.empty-state h3 {
  margin: 0 0 8px;
  font-size: 18px;
  color: #0f172a;
}

.empty-state p {
  margin: 0;
}

.btn-action {
    display: inline-block;
    padding: 8px 16px;
    border-radius: 4px;
    text-decoration: none;
    font-size: 14px;
    cursor: pointer;
    border: 1px solid transparent;
}

/* nút sửa */
.btn-edit {
    background-color: #f0f0f0;
    color: #333;
    border-color: #ccc;
}

/* nút xóa */
.btn-delete {
    background-color: #d9534f;
    color: white;
    border-color: #d9534f;
}

/* hover đẹp hơn */
.btn-action:hover {
    opacity: 0.85;
}
@media (max-width: 980px) {
  .page-layout {
    grid-template-columns: 1fr;
  }

  .sidebar {
    flex-direction: row;
    align-items: center;
    gap: 10px;
    border-right: 0;
    border-bottom: 1px solid #163364;
    padding: 10px;
  }

  .brand-block {
    border-bottom: 0;
    padding: 0;
    flex-direction: row;
    gap: 10px;
  }

  .brand-logo {
    width: 56px;
    height: 56px;
    margin-bottom: 0;
  }

  .student-info {
    text-align: left;
    margin-top: 0;
    padding-top: 0;
  }

  .student-info::before {
    display: none;
  }

  .sidebar-nav {
    margin: 0;
    flex: 1;
    flex-direction: row;
    flex-wrap: wrap;
  }

  .main-header h1 {
    font-size: 22px;
  }

  .logout-btn {
    margin-top: 0;
    border-top: 0;
    padding: 10px 12px;
  }
}

@media (max-width: 680px) {
  .main-header-top {
    padding: 10px 12px;
  }

  .school-title {
    font-size: 20px;
  }

  .main-header-bottom {
    padding: 14px 0 0 12px;
    min-height: 62px;
  }

  .page-tab {
    font-size: 18px;
    padding: 10px 14px;
  }

  .page-tab::after {
    border-top-width: 19px;
    border-bottom-width: 19px;
  }

  .toolbar {
    flex-direction: column;
  }

  .filter-group {
    flex-direction: column;
  }

  .filter-btn {
    width: 100%;
  }

  .feedback-grid {
    grid-template-columns: 1fr;
  }

  .detail-bottom-grid {
    grid-template-columns: 1fr;
  }
}

(function () {
  "use strict";

  var root = document.getElementById("chat-root");
  if (!root) {
    return;
  }

  var currentUserId = root.getAttribute("data-current-user-id") || "";
  var conversationItems = root.querySelectorAll(".conversation-item");

  var drawer = document.getElementById("chat-drawer");
  var drawerBackdrop = document.getElementById("chat-drawer-backdrop");
  var closeDrawerButton = document.getElementById("close-chat-drawer-btn");
  var drawerTitle = document.getElementById("chat-drawer-title");

  var messageList = document.getElementById("chat-message-list");
  var form = document.getElementById("chat-send-form");
  var messageInput = document.getElementById("chat-message-input");
  var fileInput = document.getElementById("chat-file-input");
  var sendButton = document.getElementById("chat-send-btn");

  if (!conversationItems.length || !drawer || !drawerBackdrop || !closeDrawerButton || !drawerTitle
      || !messageList || !form || !messageInput || !fileInput || !sendButton) {
    return;
  }

  var stompClient = null;
  var activeConversationId = "";
  var activeRequestId = "";
  var activeSubscription = null;

  setComposerEnabled(false);

  function connectWebSocket() {
    if (typeof SockJS === "undefined" || typeof Stomp === "undefined") {
      return;
    }

    var socket = new SockJS("/ws");
    stompClient = Stomp.over(socket);
    stompClient.debug = function () {};

    stompClient.connect({}, function () {});
  }

  function uploadFiles(files) {
    if (!files || files.length === 0 || !activeRequestId) {
      return Promise.resolve([]);
    }

    var formData = new FormData();
    formData.append("requestId", activeRequestId);
    for (var i = 0; i < files.length; i++) {
      formData.append("files", files[i]);
    }

    return fetch("/api/history/chat/upload", {
      method: "POST",
      body: formData,
      credentials: "same-origin"
    })
      .then(function (response) {
        if (!response.ok) {
          throw new Error("upload-failed");
        }
        return response.json();
      })
      .then(function (payload) {
        if (!payload || !Array.isArray(payload.attachments)) {
          return [];
        }
        return payload.attachments;
      });
  }

  function sendChatMessage(text, attachments) {
    if (!stompClient || !stompClient.connected || !activeRequestId) {
      return;
    }

    var payload = {
      requestId: activeRequestId,
      content: text,
      attachments: attachments || []
    };

    stompClient.send("/app/clarification/send", {}, JSON.stringify(payload));
  }

  function appendMessage(message) {
    var article = document.createElement("article");
    article.className = "chat-message";
    if (message.mine || (message.senderId && message.senderId === currentUserId)) {
      article.className += " mine";
    }

    var header = document.createElement("div");
    header.className = "chat-message-meta";

    var sender = document.createElement("strong");
    sender.textContent = message.senderName || "Người dùng";
    header.appendChild(sender);
    article.appendChild(header);

    if (message.text) {
      var text = document.createElement("p");
      text.className = "chat-message-text";
      text.textContent = message.text;
      article.appendChild(text);
    }

    if (Array.isArray(message.attachments) && message.attachments.length > 0) {
      var list = document.createElement("ul");
      list.className = "chat-attachment-list";

      for (var i = 0; i < message.attachments.length; i++) {
        var attachment = message.attachments[i];
        if (!attachment || !attachment.url) {
          continue;
        }
        var item = document.createElement("li");
        var link = document.createElement("a");
        link.href = attachment.url;
        link.target = "_blank";
        link.rel = "noopener noreferrer";
        link.textContent = attachment.name || "Tệp đính kèm";
        item.appendChild(link);
        list.appendChild(item);
      }

      if (list.children.length > 0) {
        article.appendChild(list);
      }
    }

    var timeLabel = document.createElement("div");
    timeLabel.className = "chat-message-time";
    timeLabel.textContent = message.time || "";
    article.appendChild(timeLabel);

    messageList.appendChild(article);
    messageList.scrollTop = messageList.scrollHeight;
  }

  function openDrawer() {
    drawer.classList.add("open");
    drawer.setAttribute("aria-hidden", "false");
    drawerBackdrop.hidden = false;
    document.body.style.overflow = "hidden";
  }

  function closeDrawer() {
    drawer.classList.remove("open");
    drawer.setAttribute("aria-hidden", "true");
    drawerBackdrop.hidden = true;
    document.body.style.overflow = "";
  }

  function clearMessages() {
    messageList.innerHTML = "";
  }

  function renderEmptyMessage(text) {
    clearMessages();
    var empty = document.createElement("div");
    empty.className = "chat-empty compact";
    empty.innerHTML = "<p>" + text + "</p>";
    messageList.appendChild(empty);
  }

  function renderMessages(messages) {
    clearMessages();
    if (!Array.isArray(messages) || messages.length === 0) {
      renderEmptyMessage("Chưa có tin nhắn trong cuộc hội thoại này.");
      return;
    }

    for (var i = 0; i < messages.length; i++) {
      appendMessage(messages[i]);
    }
  }

  function setComposerEnabled(enabled) {
    messageInput.disabled = !enabled;
    fileInput.disabled = !enabled;
    sendButton.disabled = !enabled;
  }

  function subscribeConversation(conversationId) {
    if (!stompClient || !stompClient.connected || !conversationId) {
      return;
    }

    if (activeSubscription) {
      activeSubscription.unsubscribe();
      activeSubscription = null;
    }

    activeSubscription = stompClient.subscribe("/topic/clarification/" + conversationId, function (frame) {
      if (!frame || !frame.body) {
        return;
      }
      try {
        var data = JSON.parse(frame.body);
        appendMessage(data);
      } catch (e) {
        // Ignore malformed frame to keep UI usable.
      }
    });
  }

  function loadConversation(conversationId) {
    return fetch("/api/history/chat/messages?conversationId=" + encodeURIComponent(conversationId), {
      method: "GET",
      credentials: "same-origin"
    }).then(function (response) {
      if (!response.ok) {
        throw new Error("load-failed");
      }
      return response.json();
    });
  }

  function activateConversation(item) {
    if (!item) {
      return;
    }

    var conversationId = item.getAttribute("data-conversation-id") || "";
    var requestId = item.getAttribute("data-request-id") || "";
    var subject = item.getAttribute("data-subject") || "Trao đổi";

    if (!conversationId || !requestId) {
      return;
    }

    activeConversationId = conversationId;
    activeRequestId = requestId;

    for (var idx = 0; idx < conversationItems.length; idx++) {
      conversationItems[idx].classList.remove("active");
    }
    item.classList.add("active");

    drawerTitle.textContent = subject;
    openDrawer();
    setComposerEnabled(true);
    renderEmptyMessage("Đang tải hội thoại...");

    loadConversation(conversationId)
      .then(function (payload) {
        if (!payload || payload.conversationId !== activeConversationId) {
          return;
        }

        activeRequestId = payload.requestId || activeRequestId;
        drawerTitle.textContent = payload.subject || subject;
        renderMessages(payload.messages || []);
        subscribeConversation(activeConversationId);
      })
      .catch(function () {
        renderEmptyMessage("Không tải được cuộc hội thoại. Vui lòng thử lại.");
      });
  }

  for (var i = 0; i < conversationItems.length; i++) {
    conversationItems[i].addEventListener("click", function () {
      activateConversation(this);
    });
  }

  closeDrawerButton.addEventListener("click", closeDrawer);
  drawerBackdrop.addEventListener("click", closeDrawer);

  form.addEventListener("submit", function (event) {
    event.preventDefault();

    if (!activeConversationId || !activeRequestId) {
      return;
    }

    var text = (messageInput.value || "").trim();
    var files = fileInput.files;

    if (!text && (!files || files.length === 0)) {
      return;
    }

    sendButton.disabled = true;

    uploadFiles(files)
      .then(function (attachments) {
        sendChatMessage(text, attachments);
        messageInput.value = "";
        fileInput.value = "";
      })
      .catch(function () {
        alert("Không thể gửi tệp đính kèm. Vui lòng thử lại.");
      })
      .finally(function () {
        sendButton.disabled = false;
      });
  });

  connectWebSocket();
})();
